#include <bits/stdc++.h>
using namespace std;
int main(){
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    long long N,M,K;
    cin>>N>>M>>K;
    vector<long long>c(K);
    for(int i=0;i<K;i++) cin>>c[i];
    set<long long>C(c.begin(),c.end());
    vector<long long>avail;
    avail.reserve(M-K);
    for(long long v=1;v<=M;v++) if(!C.count(v)) avail.push_back(v);
    long long A=avail.size();
    long long slots=N-K;
    long long T,B;
    if(slots<=(long long)K){T=slots;B=0;}
    else{B=(slots-K)/2;T=slots-B;}
    // top T from avail as rights, bottom B as lefts
    // check overlap
    if(T+B>A){// not enough available
        long long excess=T+B-A;
        B=max(0LL,B-excess);
        T=A-B;
    }
    // right elements: avail[A-T..A-1], left elements: avail[0..B-1]
    // Assign using sorted sets
    // ready_for_right: groups with R=L (can take a right), set of c values
    // need_left: groups with R=L+1 (need a left), set of c values
    // We use map from c_value -> group index
    map<long long,int>ready_map; // c->idx, groups ready for right
    map<long long,int>needleft_map; // c->idx, groups needing left
    vector<int>Li(K,0),Ri(K,0);
    vector<vector<long long>>Si(K);
    for(int i=0;i<K;i++){Si[i].push_back(c[i]);ready_map[c[i]]=i;}
    // Process right elements from largest
    // Process left elements from smallest
    long long hi=A-1,lo=0;
    long long rights_left=T,lefts_left=B;
    // We need to interleave: rights and lefts must be consistent
    // After assigning a right, group needs a left (if we plan to give more rights)
    // Strategy: assign all rights first (top T), then all lefts (bottom B)
    // For rights: for each value (largest first), find group with largest c < value in ready_map
    for(long long i=A-1;i>=A-T&&i>=0;i--){
        long long v=avail[i];
        auto it=ready_map.lower_bound(v);
        if(it!=ready_map.begin()){
            --it;
            int gi=it->second;
            Si[gi].push_back(v);
            Ri[gi]++;
            ready_map.erase(it);
            needleft_map[c[gi]]=gi;
        }
        // if no group can take it, skip (we'll handle below)
    }
    // For lefts: for each value (smallest first), find group with smallest c > value in needleft_map
    for(long long i=0;i<B&&i<A;i++){
        long long v=avail[i];
        auto it=needleft_map.upper_bound(v);
        if(it!=needleft_map.end()){
            int gi=it->second;
            Si[gi].push_back(v);
            Li[gi]++;
            needleft_map.erase(it);
            ready_map[c[gi]]=gi;
        }
    }
    // Output
    for(int i=0;i<K;i++){
        sort(Si[i].begin(),Si[i].end());
        cout<<Si[i].size();
        if(i<K-1) cout<<' ';
    }
    cout<<'\n';
    for(int i=0;i<K;i++){
        for(int j=0;j<(int)Si[i].size();j++){
            if(j) cout<<' ';
            cout<<Si[i][j];
        }
        cout<<'\n';
    }
    return 0;
}

